//! Java behaviour that the Java SE documentation specifies, shared by SimOxide and the QVTo
//! engine (EPL-2.0; `LICENSES`):
//!
//! - [`hash`]: `String.hashCode` and the boxed primitives' `hashCode`, `Double.compare`;
//! - [`fmt`]: `Double.toString`/`Float.toString` of JDK 19 and later, integer formatting;
//! - [`parse`]: `Integer.parseInt`, `Long.parseLong`, `Double.valueOf` with Java's syntax;
//! - [`chars`]: `Character` data (generated by running JDK 21: Unicode data as Java defines it);
//! - [`math`]: `Math.round`, `max`, `min`;
//! - [`order`]: the [`order::MapOrder`] interface and `LinkedHashMap`'s insertion order;
//! - [`fx`]: the Fx hasher for internal, deterministic hash maps.
//!
//! What only OpenJDK's or HotSpot's sources define (`HashMap` bucket order, HotSpot's identity
//! hashes) is in `simoxide-jcompat-exact`, an opt-in crate (cargo feature `jdk-order` of its
//! users) for the exact and compat modes.

pub mod chars;
#[rustfmt::skip]
pub mod chars_data;
pub mod fmt;
pub mod fx;
pub mod hash;
pub mod math;
pub mod order;
pub mod parse;
